#include "fw_image.h"

#include "wye_msg.h"
#include "wye_proto.h"

#include <stdlib.h>
#include <string.h>

/* Generated by cmake/embed.cmake (zero-length when firmware was not built). */
extern const unsigned char wye_fw_bridge_uf2[];
extern const size_t wye_fw_bridge_uf2_len;
extern const unsigned char wye_fw_target_uf2[];
extern const size_t wye_fw_target_uf2_len;

#define UF2_BLOCK 512u
#define UF2_MAGIC0 0x0a324655u
#define UF2_MAGIC1 0x9e5d5157u
#define UF2_FLAG_FAMILY 0x00002000u
#define UF2_MAX_IMAGE (1024u * 1024u)

const struct wye_fw_image *wye_fw_embedded(uint8_t role)
{
    static struct wye_fw_image images[2];
    struct wye_fw_image *img = &images[role == WYE_ROLE_TARGET];
    img->role = role;
    img->name = role == WYE_ROLE_TARGET ? "target" : "bridge";
    img->uf2 = role == WYE_ROLE_TARGET ? wye_fw_target_uf2 : wye_fw_bridge_uf2;
    img->uf2_len = role == WYE_ROLE_TARGET ? wye_fw_target_uf2_len : wye_fw_bridge_uf2_len;
    img->major = WYE_VERSION_MAJOR;
    img->minor = WYE_VERSION_MINOR;
    img->patch = WYE_VERSION_PATCH;
    return img->uf2_len >= UF2_BLOCK ? img : NULL;
}

bool wye_fw_is_older(const struct wye_fw_image *img, uint8_t major, uint8_t minor, uint8_t patch)
{
    uint32_t have = (uint32_t)major << 16 | (uint32_t)minor << 8 | patch;
    uint32_t want = (uint32_t)img->major << 16 | (uint32_t)img->minor << 8 | img->patch;
    return have < want;
}

bool wye_uf2_to_bin(const uint8_t *uf2, size_t len, uint8_t **bin, size_t *bin_len)
{
    uint8_t *out = malloc(UF2_MAX_IMAGE);
    size_t end = 0;
    if (!out || len % UF2_BLOCK != 0) {
        free(out);
        return false;
    }
    memset(out, 0xff, UF2_MAX_IMAGE);
    for (size_t off = 0; off < len; off += UF2_BLOCK) {
        const uint8_t *b = uf2 + off;
        uint32_t flags = wye_get_u32(b + 8), addr = wye_get_u32(b + 12), size = wye_get_u32(b + 16);
        bool magic = wye_get_u32(b) == UF2_MAGIC0 && wye_get_u32(b + 4) == UF2_MAGIC1;
        bool family = !(flags & UF2_FLAG_FAMILY) || wye_get_u32(b + 28) == WYE_UF2_FAMILY_RP2040;
        if (!magic || !family || size > 476 || addr < WYE_FLASH_BASE ||
            addr - WYE_FLASH_BASE + size > UF2_MAX_IMAGE) {
            free(out);
            return false;
        }
        memcpy(out + (addr - WYE_FLASH_BASE), b + 32, size);
        if (addr - WYE_FLASH_BASE + size > end) {
            end = addr - WYE_FLASH_BASE + size;
        }
    }
    *bin = out;
    *bin_len = end;
    return end > 0;
}
